1	import { useEffect, useRef } from 'react';
2	import gsap from 'gsap';
3	import { ScrollTrigger } from 'gsap/ScrollTrigger';
4	
5	gsap.registerPlugin(ScrollTrigger);
6	
7	/**
8	 * Initializes Lenis smooth scroll + GSAP ScrollTrigger for the editorial layout,
9	 * then wires scroll-reveal choreography to real sections via data attributes.
10	 *
11	 * Data attribute contract (consumed by this hook):
12	 *   [data-motion-hero]    — opening name/lede block; fades + rises on page load
13	 *   [data-motion-reveal]  — section reveal groups; fade + translate on scroll enter
14	 *   [data-motion-ready]   — stamped on <html> once choreography is initialised
15	 *
16	 * When prefers-reduced-motion is active the hook skips Lenis and GSAP entirely,
17	 * marks <html data-reduced-motion="true"> so CSS can respond, and returns early.
18	 *
19	 * Usage: call once at the root component level.
20	 *   const { reducedMotion } = useEditorialMotion();
21	 *
22	 * Returns:
23	 *   { reducedMotion: boolean }
24	 */
25	export function useEditorialMotion() {
26	  const lenisRef = useRef(null);
27	  const reducedMotion =
28	    typeof window !== 'undefined' &&
29	    window.matchMedia('(prefers-reduced-motion: reduce)').matches;
30	
31	  useEffect(() => {
32	    // Always stamp the attribute so CSS rules are predictable.
33	    document.documentElement.setAttribute(
34	      'data-reduced-motion',
35	      reducedMotion ? 'true' : 'false'
36	    );
37	
38	    if (reducedMotion) return;
39	
40	    let tickerFn;
41	
42	    try {
43	      // Dynamic import keeps the bundle split-friendly and lets us catch load failures.
44	      import('lenis').then(({ default: Lenis }) => {
45	        const lenis = new Lenis({
46	          duration: 1.2,
47	          easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
48	          orientation: 'vertical',
49	          gestureOrientation: 'vertical',
50	          smoothWheel: true,
51	        });
52	
53	        lenisRef.current = lenis;
54	
55	        // Wire Lenis into the GSAP ticker so ScrollTrigger stays in sync.
56	        tickerFn = (time) => lenis.raf(time * 1000);
57	        gsap.ticker.add(tickerFn);
58	        gsap.ticker.lagSmoothing(0);
59	
60	        // Let ScrollTrigger proxy scroll events through Lenis.
61	        ScrollTrigger.scrollerProxy(document.documentElement, {
62	          scrollTop(value) {
63	            if (arguments.length) {
64	              lenis.scrollTo(value, { immediate: true });
65	            }
66	            return lenis.scroll;
67	          },
68	          getBoundingClientRect() {
69	            return {
70	              top: 0,
71	              left: 0,
72	              width: window.innerWidth,
73	              height: window.innerHeight,
74	            };
75	          },
76	        });
77	
78	        lenis.on('scroll', ScrollTrigger.update);
79	
80	        // ── Hero entrance (page-load, not scroll-triggered) ──────────────────
81	        const heroEls = document.querySelectorAll('[data-motion-hero]');
82	        if (heroEls.length) {
83	          gsap.fromTo(
84	            heroEls,
85	            { opacity: 0, y: 28 },
86	            {
87	              opacity: 1,
88	              y: 0,
89	              duration: 1.1,
90	              ease: 'power3.out',
91	              stagger: 0.12,
92	              clearProps: 'transform',
93	            }
94	          );
95	        }
96	
97	        // ── Section reveal on scroll enter ───────────────────────────────────
98	        const revealEls = document.querySelectorAll('[data-motion-reveal]');
99	        revealEls.forEach((el) => {
100	          gsap.fromTo(
101	            el,
102	            { opacity: 0, y: 40 },
103	            {
104	              opacity: 1,
105	              y: 0,
106	              duration: 0.9,
107	              ease: 'power2.out',
108	              clearProps: 'transform',
109	              scrollTrigger: {
110	                trigger: el,
111	                start: 'top 82%',
112	                toggleActions: 'play none none none',
113	                once: true,
114	              },
115	            }
116	          );
117	        });
118	
119	        ScrollTrigger.refresh();
120	
121	        // Signal to CSS / devtools that motion is live.
122	        document.documentElement.setAttribute('data-motion-ready', 'true');
123	        if (process.env.NODE_ENV !== 'production') {
124	          console.debug(
125	            '[useEditorialMotion] init — heroes:', heroEls.length,
126	            '| reveals:', revealEls.length
127	          );
128	        }
129	      }).catch((err) => {
130	        if (process.env.NODE_ENV !== 'production') {
131	          console.error('[useEditorialMotion] Lenis/GSAP init failed:', err.message);
132	        }
133	      });
134	    } catch (err) {
135	      if (process.env.NODE_ENV !== 'production') {
136	        console.error('[useEditorialMotion] Lenis/GSAP init failed:', err.message);
137	      }
138	    }
139	
140	    return () => {
141	      if (lenisRef.current) {
142	        lenisRef.current.destroy();
143	        lenisRef.current = null;
144	      }
145	      if (tickerFn) gsap.ticker.remove(tickerFn);
146	      ScrollTrigger.killAll();
147	      ScrollTrigger.clearScrollMemory();
148	      document.documentElement.removeAttribute('data-motion-ready');
149	    };
150	  }, []); // eslint-disable-line react-hooks/exhaustive-deps
151	
152	  return { reducedMotion };
153	}
